						const body = "\n<div id=\"global-bg-effect\" class=\"hero-bg-effect\">\n<div class=\"hero-glow-line hero-glow-line--indigo-blur\">\n</div>\n<div class=\"hero-glow-line hero-glow-line--indigo\">\n</div>\n<div class=\"hero-glow-line hero-glow-line--sky-blur\">\n</div>\n<div class=\"hero-glow-line hero-glow-line--sky\">\n</div>\n<canvas id=\"hero-sparkle-canvas\">\n</canvas>\n</div>\n<a href=\"essays.html\" class=\"note-back-fixed\" data-lenis-prevent>\n&larr; Back\n</a>\n<section class=\"essay-hero\">\n<div class=\"container\">\n<h1 class=\"essay-hero-title\">\n不是做错什么，\n<br />而是没做对什么\n</h1>\n<div class=\"essay-meta\">\n<span class=\"essay-date\">\n2026.07.06\n</span>\n<span class=\"essay-tag\">\nBusiness\n</span>\n</div>\n</div>\n</section>\n<article class=\"essay-content section\">\n<div class=\"container\">\n<div class=\"essay-body\">\n<div class=\"essay-quote-block\">\n<p class=\"essay-quote-text\">\n今天刷到一个非常感慨的事情，健身服务 Keep 因递交招股书 6 个月内未通过聆讯，IPO 申请状态已转为「失败」，这大概率意味着本次冲刺 IPO 失败了。\n</p>\n<p class=\"essay-quote-text\">\n9 轮融资了超过 8 亿美金、估值 130 亿如今沦为「卖货」平台，2021 年前三个季度，Keep 亏损更是达到 24.58 亿元。在 Web2.0 的世界里，资本退出最大的路径就是上市，但大环境直接扼杀了这条路径。\n</p>\n<p class=\"essay-quote-text\">\n对比下类似的 Web3 应用 Stepn，同样赛道、相似的用户群、百分之一的用户数，上线不到一年估值就超过了 10 亿美金，更关键的是，项目方赚钱啊，实实在在的真金白银，Stepn 月收入超 7 亿元，每日交易费用净利润达 3342 万元，而 Stepn 用户仅仅有 300 万不到，Keep 用户超过 3 亿。\n</p>\n</div>\n<p class=\"essay-conclusion\">\n有时候不是你做错什么，而是你没做对什么。\n</p>\n</div>\n</div>\n</article>\n";
